mapper.update:
UPDATE product
SET prdName=#{prdName}, prdPrice=#{prdPrice}, prdCompany=#{prdCompany, jdbcType=VARCHAR},
    prdStock=#{prdStock}, prdDescript=#{prdDescript, jdbcType=VARCHAR}, ctgId=#{ctgId},
    minPlayer=#{minPlayer}, maxPlayer=#{maxPlayer}, playTime=#{playTime}, difficulty=#{difficulty}
WHERE prdNo=#{prdNo}

mapper.select:
SELECT * FROM product
WHERE minPlayer <= #{max} AND maxPlayer >= #{min}
ORDER BY prdNo
